// SATUSEHAT STG Ingress & Auto-Token
var raw = JSON.parse(input);
var hospitalCode = raw.hospital_code || raw.hospitalCode || raw.tenant_id || "";
var resourceType = raw.resource || raw.resourceType || (raw.data && raw.data.resourceType) || "";
var httpMethod = (raw.method || "POST").toUpperCase();
var resourceId = raw.resource_id || raw.id || "";
var fhirData = raw.data || raw.payload || raw;

if (!resourceType) throw new Error("Missing resourceType");

var orgId = getRouteVar("ORG_ID") || "";
var clientId = getRouteVar("CLIENT_ID") || "";
var clientSecret = getRouteVar("CLIENT_SECRET") || "";

if (hospitalCode) {
  var tenantsJson = getGlobalVar("TENANT_CREDENTIALS");
  if (tenantsJson) {
    try {
      var t = JSON.parse(tenantsJson)[hospitalCode];
      if (t) {
        var cfg = t.satusehat || t;
        orgId = cfg.org_id || orgId;
        clientId = cfg.client_id || clientId;
        clientSecret = cfg.client_secret || clientSecret;
      }
    } catch(e) {}
  }
}

var cacheKey = "satusehat_stg_token_" + (hospitalCode || orgId || clientId);
var token = cache.get(cacheKey);

if (!token) {
  var authUrl = getRouteVar("AUTH_URL") || "https://api-satusehat-stg.kemkes.go.id/oauth2/v1/accesstoken?grant_type=client_credentials";
  var res = http.request({
    url: authUrl,
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: "client_id=" + encodeURIComponent(clientId) + "&client_secret=" + encodeURIComponent(clientSecret)
  });
  if (res.status !== 200) throw new Error("Auth failed: " + res.status + " " + res.body);
  var auth = JSON.parse(res.body);
  token = auth.access_token;
  var ttl = Math.max(300, (parseInt(auth.expires_in, 10) || 3600) - 300);
  cache.set(cacheKey, token, ttl);
}

var baseUrl = (getRouteVar("FHIR_BASE_URL") || "https://api-satusehat-stg.kemkes.go.id/fhir-r4/v1").replace(/\/+$/, "");
var targetUrl = baseUrl + "/" + resourceType + (resourceId ? "/" + resourceId : "");

return JSON.stringify({
  __dispatch: {
    url: targetUrl,
    method: httpMethod,
    headers: { "Authorization": "Bearer " + token, "Content-Type": "application/json" }
  },
  payload: fhirData
});
